// v27: careers URLs that can never be scraped as given, mapped to the real board.
// [test, rewrite] — first match wins, applied before routing so the right handler is chosen.
const BOARD_REWRITES = [
  // some careers pages sit behind a Queue-it waiting room while the underlying ATS board does not.
  [/(^|\.)example-org\.org\b/i, function () { return 'https://jobs.jobvite.com/example/search'; }],
];
function rewriteBoard(u) {
  for (let i = 0; i < BOARD_REWRITES.length; i++) {
    const host = (String(u).match(/^https?:\/\/([^\/?#]+)/i) || [])[1] || '';
    if (BOARD_REWRITES[i][0].test(host)) return BOARD_REWRITES[i][1](u);
  }
  return u;
}

// ── v40 (2026-08-08): scheduled batches ─────────────────────────────────────────────────────
// The sheet button is unchanged — PRIORITY-ONLY, exactly as before. A Schedule Trigger run
// instead takes a fixed slice of the Companies tab, so nothing has to be marked by hand:
//   08:00 PHT → batch 1 · 09:00 → 2 · 10:00 → 3 · 11:00 → 4, EVERY day (v46: the 12:00 one-link
//   batch was removed at the request — One Link now runs only from the manual sheet button)
//   (v42: Tue–Sat
//   skipped the expected Sunday start, and an idle-looking schedule is worse than a low-yield run)
// Sizes come from the MEASURED runtime of the 2026-08-08 full run (306 companies / 116 min), not
// from company count: the mega-boards sit together, so an equal-count split would give a 45-minute
// batch next to a 15-minute one. Retune here and nowhere else.
// v42 — re-derived after operator re-sorted the tab (weights carried across by Job Link):
//   100 / 91 / 55 / 61 companies = 29 / 29 / 28 / 29 min. The v40 sizes still gave 29/30/29/28 on
//   the new order, which is the point: a time-balanced split makes a re-sort a non-event.
const BATCH_SIZES = [100, 91, 55];   // batches 1-3; batch 4 takes everything left over

// Never-scrape statuses, settled with operator 2026-08-08: Indeed/LinkedIn-only boards, postings with
// no details or no salary, and companies whose jobs are all outside the 10 states. Matched on the
// STATUS text rather than the company name so re-sorting the sheet cannot break it.
// ⚠️ Must not catch "Site has no job" or "Site has one job ok" — different strings, both still run.
// v79 (2026-09-01): operator relabelled the Status column again — "Website not allowed - Indeed",
// "Website Job has no salary/details", "Website Job states not allowed". Added alongside the old
// wordings, never replacing them, so a row the operator has not relabelled behaves identically.
// ⚠️ "Website HAS NO JOB posting" must NOT match this (it IS collected, and normally returns 0) —
//    hence `website job has no`, which needs the word "job" immediately after "website".
const NEVER_SCRAPE = /^(?:site not allowed|states not allowed|site's job has no|website not allowed|website job (?:has no|states not allowed))/i;
// v47 (2026-08-10) ��� operator: on the SCHEDULE, fetch ONLY these statuses. An allowlist, deliberately:
// the v40 blocklist fetched anything it did not recognise, so when column E was briefly cleared the
// 11:00 batch collected the 12 one-link + 7 per-job rows as ordinary boards. Unknown/blank now skips.
// ⚠️ Prefix match — "Site has one job ok" is a real variant and must stay allowed.
// v71 (2026-09-01) — operator re-labelled the tab: "Site has one job" became "one job", and
// "two jobs" / "one only" / "site error" appeared. An allowlist SKIPS what it does not
// recognise, so 21 companies — including every "two jobs" row — had
// silently dropped off the daily run between the 03:00 batch and the evening of 8/31.
// ⚠️ "one job" is NOT "one link": OFFLOAD is still tested after this and still wins.
// v79 (2026-09-01): "Less than 3 jobs" replaces "one job"/"two jobs", "Website has no job posting"
// replaces "Site has no job", "Website error" replaces "site error".
// ⚠️ THIRD time a relabelling has silently emptied part of the schedule. Measured on the live tab
//    before this patch: 59 companies uncollected — 36 "Less than 3 jobs", 21 "Website has no job
//    posting", 2 "Website error". The allowlist is right; it fails safe by SKIPPING, which is why
//    every new wording has to be added here, and why v71 made the skipped rows show up in Slack.
// ⚠️ Old tokens KEPT: a row still carrying an old label must keep running.
const SCHED_ALLOW = /^(?:ok|scrape nationally|site has no job|site has one job|one job|one only|two jobs|site error|less than \d+ jobs?|website has no job|website error)\b/i;
const OFFLOAD = /\b(?:one[\s_-]*link|per[\s_-]*job)\b/i;

let scheduled = false;
try { scheduled = $('Schedule Trigger').isExecuted === true; } catch (e) { scheduled = false; }

// The Schedule Trigger prints Hour in the workflow timezone (Asia/Manila). Intl is the fallback so
// a renamed/absent field can never silently collapse every run into batch 1.
let batch = 1;
if (scheduled) {
  let hh = null;
  try { hh = Number($('Schedule Trigger').first().json.Hour); } catch (e) { hh = null; }
  if (!isFinite(hh)) {
    hh = Number(new Intl.DateTimeFormat('en-US', { hour: 'numeric', hour12: false, timeZone: 'Asia/Manila' }).format(new Date()));
  }
  batch = Math.min(4, Math.max(1, hh - 7));   // 08:00 → 1 … 11:00 → 4 (v46: no batch 5)
}

const out = [];
const pool = [];            // scheduled runs collect here first, then get sliced into the batch
let oneLinkSkipped = 0;
const oneLinkNames = [];
for (const item of $input.all()) {
  const j = item.json;
  const rawLink = String(j['Job Link'] || '').trim();
  if (!rawLink || !/^https?:\/\//i.test(rawLink)) continue;
  const status = String(j.Status || '');
  if (NEVER_SCRAPE.test(status)) continue;                              // v40
  if (scheduled && !SCHED_ALLOW.test(status.trim())) continue;          // v47: allowlist on the schedule
  const link = rewriteBoard(rawLink);
  if (!scheduled && String(j.Priority || '').trim() === '') continue; // PRIORITY-ONLY: only companies marked in col E run
  // One-link companies are handled by "Job Link OS - One Link Companies" instead:
  // their whole careers page is read there and each posting is cross-checked against
  // the masterlist. Collecting them here would push a careers-page URL — or an outbound
  // LinkedIn/Indeed apply link — into LIST, and neither is a job link.
  if (OFFLOAD.test(status)) {
    // v46: a scheduled run NEVER hands off — one_link_pending stays 0 on all four batches, so
    // "One Link Selected?" cannot fire. The manual button still counts them (scheduled === false).
    if (scheduled) continue;
    oneLinkSkipped++; oneLinkNames.push(String(j.Company || '').trim()); continue;
  }
  let route = 'html';
  if (/tbe\.taleo\.net/i.test(link)) route = 'taleo';
  else if (/workforcenow\.adp\.com[^\s]*[?&]cid=/i.test(link)) route = 'api';
  else if (/(ultipro\.com|rec\.pro\.ukg\.net)\/[^\/]+\/JobBoard\/[0-9a-fA-F-]/i.test(link)) route = 'api';
  (scheduled ? pool : out).push({ json: {
    row_number: j.row_number,
    record_id: String(j.row_number),
    company: String(j.Company || '').trim(),
    job_link: link,
    sheet_link: rawLink,
    link_rewritten: link !== rawLink,
    last_fetched: j['Last Update'] || '',
    priority: true,
    is_taleo: route === 'taleo',
    is_api: route === 'api',
    route: route
  } });
}
if (scheduled && batch !== 5) {
  // v40: sheet order is the batch order. BATCH_SIZES covers batches 1-3; the last batch is
  // "everything from here on", so a company added to the bottom of the tab is picked up by the
  // schedule the next day with no code change.
  pool.sort(function (a, b) { return (a.json.row_number || 0) - (b.json.row_number || 0); });
  let from = 0;
  for (let i = 0; i < batch - 1; i++) from += (BATCH_SIZES[i] || 0);
  const size = BATCH_SIZES[batch - 1];
  const slice = (size === undefined) ? pool.slice(from) : pool.slice(from, from + size);
  for (let i = 0; i < slice.length; i++) out.push(slice[i]);
}
if (!out.length) {
  if (oneLinkSkipped) {
    // Every selected company is a one-link company. They are running — in the One Link
    // Companies workflow, which fills in column G as it goes — so list them by name the
    // way a normal run does. warning:true keeps them out of this workflow's Loop.
    return oneLinkNames.map(function (nm, i) {
      return { json: { warning: true, handed_off: true, company: nm, job_link: '',
        queue_pos: i + 1, queue_total: oneLinkNames.length,
        one_link_pending: oneLinkSkipped, one_link_names: oneLinkNames } };
    });
  }
  // nothing marked at all: single warning row (shown in the Run Queue cell)
  return [{ json: { warning: true, company: '⚠️ NO COMPANY SELECTED — put 1 in Priority (col E) first',
    job_link: '', queue_pos: 1, queue_total: 0, one_link_pending: 0, one_link_names: [] } }];
}
out.sort(function (a, b) { return (a.json.row_number || 0) - (b.json.row_number || 0); });
out.forEach(function (it, i) {
  it.json.queue_pos = i + 1;
  it.json.queue_total = out.length;
  it.json.run_mode = scheduled ? ('schedule-batch-' + batch) : 'manual';   // v40
  // read by "One Link Selected?" — those companies are handed to the One Link workflow
  it.json.one_link_pending = oneLinkSkipped;
  it.json.one_link_names = oneLinkNames;
});
return out;

const ALLOWED = new Set(['CA','CT','IL','DC','NJ','NY','RI','VA','MD','WA']);
const item = $input.item.json;
const baseUrl = item.job_link;
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36';
const jobs = new Map();

let reqBase = null;
const m0 = baseUrl.match(/^(https?:\/\/[^\/]+\/[^\/]+)\/ats\/careers\/v2/i);
if (m0) reqBase = m0[1] + '/ats/careers/v2/viewRequisition';

// Some Taleo BE boards use a generic share title ("View job details and apply now") with no location,
// so we ALSO parse the plain viewJobLink anchors for real titles, and later fetch detail pages for state-less jobs.
function parsePage(html) {
  const re = /viewRequisition%3Forg%3D([A-Z0-9]+)%26cws%3D(\d+)%26rid%3D(\d+)&title=([^&]+)&/g;
  let m, added = 0;
  while ((m = re.exec(html)) !== null) {
    const org = m[1], cws = m[2], rid = m[3], rawTitle = m[4];
    if (jobs.has(rid)) continue;
    added++;
    let full = rawTitle.replace(/\+/g, ' ');
    try { full = decodeURIComponent(full); } catch (e) {}
    let title = full.replace(/^Hiring /, '');
    if (/^View job details/i.test(title)) title = '';
    const parts = title.split(' - ');
    const location = title ? parts[parts.length - 1].trim() : '';
    const stMatch = location.match(/,\s*([A-Z]{2})$/);
    const state = stMatch ? stMatch[1] : null;
    const urlBase = reqBase || 'https://phe.tbe.taleo.net/phe03/ats/careers/v2/viewRequisition';
    jobs.set(rid, { title: title, location: location, state: state, url: urlBase + '?org=' + org + '&cws=' + cws + '&rid=' + rid });
  }
  const reA = /<a href="(https?:\/\/[^"]*viewRequisition\?org=([A-Z0-9]+)&(?:amp;)?cws=(\d+)&(?:amp;)?rid=(\d+))"[^>]*class="viewJobLink"[^>]*>([^<]+)</g;
  let a;
  while ((a = reA.exec(html)) !== null) {
    const rid = a[4];
    const aTitle = a[5].replace(/\s+/g, ' ').trim();
    if (jobs.has(rid)) {
      const j = jobs.get(rid);
      if (!j.title) j.title = aTitle;
      if (!j.state) {
        const sm2 = aTitle.match(/,\s*([A-Z]{2})\s*$/);
        if (sm2) j.state = sm2[1];
      }
    } else {
      added++;
      const sm2 = aTitle.match(/,\s*([A-Z]{2})\s*$/);
      jobs.set(rid, { title: aTitle, location: '', state: sm2 ? sm2[1] : null, url: a[1].replace(/&amp;/g, '&') });
    }
  }
  return added;
}

let fetch_ok = true, fetch_error = '';
try {
  const first = await this.helpers.httpRequest({ url: baseUrl, method: 'GET', returnFullResponse: true, headers: { 'User-Agent': UA }, timeout: 60000 });
  const rawCookies = first.headers['set-cookie'] || [];
  const cookieList = Array.isArray(rawCookies) ? rawCookies : [rawCookies];
  const cookie = cookieList.map(function (c) { return String(c).split(';')[0]; }).join('; ');
  const body1 = typeof first.body === 'string' ? first.body : JSON.stringify(first.body);
  let added = parsePage(body1);
  let offset = 10, pages = 1;
  while (added > 0 && pages < 30) {
    const sep = baseUrl.indexOf('?') >= 0 ? '&' : '?';
    const pageUrl = baseUrl + sep + 'rowFrom=' + offset;
    const headers = { 'User-Agent': UA };
    if (cookie) headers.Cookie = cookie;
    const res = await this.helpers.httpRequest({ url: pageUrl, method: 'GET', headers: headers, timeout: 60000 });
    const body = typeof res === 'string' ? res : JSON.stringify(res);
    added = parsePage(body);
    offset += 10;
    pages++;
  }
  // Resolve state-less jobs from their detail pages ("New Bern, NC / Full-time" style line), batches of 5, cap 60.
  const nulls = Array.from(jobs.values()).filter(function (j) { return !j.state; }).slice(0, 60);
  const fetchDetail = async function (j) {
    try {
      const res = await this.helpers.httpRequest({ url: j.url, method: 'GET', headers: { 'User-Agent': UA }, timeout: 45000 });
      const body = typeof res === 'string' ? res : JSON.stringify(res);
      const text = body.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ');
      const lm = text.match(/([A-Za-z .'-]{2,40},\s*([A-Z]{2}))\s*\/\s*(Full|Part|Per[- ]?Diem|PRN|Temp|Seasonal|Intern|Contract)/i);
      if (lm) { j.location = lm[1].trim(); j.state = lm[2]; }
    } catch (e) {}
  }.bind(this);
  for (let i = 0; i < nulls.length; i += 5) {
    await Promise.all(nulls.slice(i, i + 5).map(function (j) { return fetchDetail(j); }));
  }
} catch (e) {
  fetch_ok = jobs.size > 0;
  fetch_error = (e && e.message) ? e.message : String(e);
}

const all = Array.from(jobs.values());
const allowed = all.filter(function (j) { return j.state && ALLOWED.has(j.state); });
return { json: Object.assign({}, item, { fetch_ok: fetch_ok, fetch_error: fetch_error, total_found: all.length, jobs: allowed }) };

const ALLOWED = new Set(['CA','CT','IL','DC','NJ','NY','RI','VA','MD','WA']);
const ALL_STATES = new Set(['AL','AK','AZ','AR','CA','CO','CT','DE','DC','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY']);
const NAME2CODE = { 'alabama':'AL','alaska':'AK','arizona':'AZ','arkansas':'AR','california':'CA','norcal':'CA','socal':'CA','colorado':'CO','connecticut':'CT','delaware':'DE','district of columbia':'DC','florida':'FL','georgia':'GA','hawaii':'HI','idaho':'ID','illinois':'IL','indiana':'IN','iowa':'IA','kansas':'KS','kentucky':'KY','louisiana':'LA','maine':'ME','maryland':'MD','massachusetts':'MA','michigan':'MI','minnesota':'MN','mississippi':'MS','missouri':'MO','montana':'MT','nebraska':'NE','nevada':'NV','new hampshire':'NH','new jersey':'NJ','new mexico':'NM','new york':'NY','north carolina':'NC','north dakota':'ND','ohio':'OH','oklahoma':'OK','oregon':'OR','pennsylvania':'PA','rhode island':'RI','south carolina':'SC','south dakota':'SD','tennessee':'TN','texas':'TX','utah':'UT','vermont':'VT','virginia':'VA','washington':'WA','west virginia':'WV','wisconsin':'WI','wyoming':'WY' };
const NAME_RE = new RegExp('\\b(' + Object.keys(NAME2CODE).sort(function (a, b) { return b.length - a.length; }).join('|') + ')\\b', 'gi');
const EXCLUDE_RE = /\/(ajax|login|register|signin|sign-in|signup|sign-up|createaccount|forgotpassword|jobalerts?|job-alerts?|talent-?community|saved-?jobs|benefits|privacy|terms)\b/i;

const ctx = $('Loop (rate limit)').item.json;
const resp = $input.item.json;
const statusCode = resp.statusCode || 0;
let html = '';
const b = resp.body || resp;
if (typeof b === 'string') html = b;
else if (b && typeof b === 'object') {
  if (Array.isArray(b.results) && b.results.length) html = String(b.results[0].content || '');
  else if (typeof b.content === 'string') html = b.content;
  else if (typeof b.data === 'string') html = b.data;
}
if (!html || html.length < 500) {
  try {
    let direct = await this.helpers.httpRequest({ url: ctx.job_link, method: 'GET', headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36', Accept: 'text/html' }, timeout: 60000 });
    if (typeof direct !== 'string') direct = JSON.stringify(direct);
    if (direct && direct.length > html.length) html = direct;
  } catch (e) {}
}
const fetch_ok = html.length > 500;
const jobs = new Map();

function absolutize(href, base) {
  href = String(href || '').trim().replace(/&amp;/g, '&');
  if (!href || /^(javascript:|mailto:|tel:|#)/i.test(href)) return null;
  if (/^https?:\/\//i.test(href)) return href;
  const mB = base.match(/^(https?:)\/\/([^\/?#]+)([^?#]*)?/i);
  if (!mB) return null;
  const proto = mB[1], host = mB[2];
  if (href.indexOf('//') === 0) return proto + href;
  if (href.charAt(0) === '/') return proto + '//' + host + href;
  let basePath = mB[3] || '/';
  basePath = basePath.replace(/[^\/]*$/, '');
  return proto + '//' + host + basePath + href;
}

// v27: a bare [A-Z]{2} token that happens to be a state code is NOT proof of a state.
// "Resident Aide I (South LA)" and "LA County Department of Mental Health"
// both resolved to LA=Louisiana and silently deleted 6 real Los Angeles jobs. Codes are now
// STRONG only with address context (comma before -> "City, ST", or a ZIP after); everything else
// is WEAK. Weak hits still tag/keep a job, but only a STRONG non-allowed hit may drop one, so this
// can never start dropping something that is kept today.
// v30: ';' and '|' are separators too (see Probe Careers API).
const CODE_RE_V27 = /([,;|\s(\/-])([A-Z]{2})(?=[\s,;|).\/-]|$)/g;
// v37: "Port Washington, WI" / "Fort Washington, Pennsylvania 19034" both scanned as WASHINGTON —
// 13 jobs in Wisconsin and 18 more at a Fort Washington PA head office
// went into the sheet as Washington State. A state NAME is the CITY, not the state, when it is
// (a) preceded with no separator by a capitalised word that is not a connector, and (b) immediately
// followed by ", <another state>". It can only demote a name that a more specific state token
// follows, and that token is added in its place, so no window that resolves today comes back empty.
const V37_CONNECTORS = /^(in|at|of|for|to|and|or|from|near|the|greater|remote|onsite|hybrid|within|across|serving|throughout|state|states|county|counties|city|area|region|west|east|north|south|central|northern|southern|eastern|western)$/i;
function v37NextState(post) {
  const cm = post.match(/^\s*,\s*([A-Za-z]{2})(?=[\s,;|).\/-]|$)/);
  if (cm && ALL_STATES.has(cm[1].toUpperCase())) return cm[1].toUpperCase();
  const nm2 = post.match(/^\s*,\s*([A-Za-z][A-Za-z ]{2,20}?)(?=[\s,;|).\/-]|\d|$)/);
  if (nm2) { const c = NAME2CODE[nm2[1].trim().toLowerCase()]; if (c) return c; }
  return null;
}
function v37IsCityName(textWin, index, matched, code) {
  const pre = textWin.slice(Math.max(0, index - 30), index);
  const preWordM = pre.match(/([A-Za-z][A-Za-z.'-]*)\s+$/);
  if (!preWordM) return false;
  const w = preWordM[1];
  if (w !== w.toUpperCase() && w[0] !== w[0].toUpperCase()) return false;
  if (V37_CONNECTORS.test(w.replace(/[.'-]/g, ''))) return false;
  const next = v37NextState(textWin.slice(index + matched.length, index + matched.length + 30));
  return !!next && next !== code;
}
// v38: "Washington, District of Columbia" and "Washington, D.C." are the CITY
// Washington, not Washington State — one board filed 38 of its 53 postings that way and
// every one of them came out tagged WA. Normalising the phrase away before the scan removes the
// "washington" token and leaves "district of columbia", which resolves to DC. DC and WA are both
// allowed states, so this can only ever change a label, never a keep/drop decision. (Flagged as a
// cosmetic leftover in v25; that board is what made it worth fixing.)
function v38DcNormalise(t) {
  return String(t || '').replace(/\bwashington\b\s*,?\s*(?:d\.?\s*c\.?|district\s+of\s+columbia)\b/gi, 'District of Columbia');
}
function scanStates(rawWindow) {
  const textWin = v38DcNormalise(rawWindow.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ')); // v38: "Washington, D.C." is the city Washington
  const strong = [];
  const weak = [];
  let cm;
  CODE_RE_V27.lastIndex = 0;
  while ((cm = CODE_RE_V27.exec(textWin)) !== null) {
    const code = cm[2];
    if (!ALL_STATES.has(code)) continue;
    const after = textWin.slice(cm.index + cm[0].length, cm.index + cm[0].length + 12);
    // cm[1] holds only the single delimiter char and "Miami, FL" puts a space there, so look back
    // across the whitespace run for the comma that makes this a real "City, ST" address.
    const before = textWin.slice(Math.max(0, cm.index - 40), cm.index + 1);
    const bucket = (/,\s*$/.test(before) || /^[\s,]*\d{5}(?:-\d{4})?\b/.test(after)) ? strong : weak;
    if (bucket.indexOf(code) === -1) bucket.push(code);
  }
  let nm;
  NAME_RE.lastIndex = 0;
  while ((nm = NAME_RE.exec(textWin)) !== null) {
    const code = NAME2CODE[nm[1].toLowerCase()];
    if (!code) continue;
    if (v37IsCityName(textWin, nm.index, nm[1], code)) continue; // v37: "Port Washington, WI"
    if (strong.indexOf(code) === -1) strong.push(code); // spelled-out state name is always strong
  }
  const all = strong.slice();
  for (let i = 0; i < weak.length; i++) if (all.indexOf(weak[i]) === -1) all.push(weak[i]);
  return { all: all, strong: strong };
}
function detectStates(rawWindow) { return scanStates(rawWindow).all; }

const taleoRe = /viewRequisition%3Forg%3D([A-Z0-9]+)%26cws%3D(\d+)%26rid%3D(\d+)&title=([^&]+)&/g;
let tm;
while ((tm = taleoRe.exec(html)) !== null) {
  const rid = tm[3];
  const key = 'taleo-' + rid;
  if (jobs.has(key)) continue;
  let full = tm[4].replace(/\+/g, ' ');
  try { full = decodeURIComponent(full); } catch (e) {}
  const title = full.replace(/^Hiring /, '');
  const parts = title.split(' - ');
  const location = parts[parts.length - 1].trim();
  const stMatch = location.match(/,\s*([A-Z]{2})$/);
  const state = stMatch ? stMatch[1] : null;
  if (state && !ALLOWED.has(state)) continue;
  jobs.set(key, { url: 'https://phe.tbe.taleo.net/phe03/ats/careers/v2/viewRequisition?org=' + tm[1] + '&cws=' + tm[2] + '&rid=' + rid, state: state, title: title });
}

