// return the same job page (same status, same <title>). embed / embedded are NOT stripped —
// jobs.silkroad.com redirects to the company board without ?embedded=true.
// The fragment (#jobapplication, #job) is kept, except a bare colour (#FFFFFF = the tail of
// an ATS skin's ssbgcolor=#FFFFFF, which the URL parser reads as a fragment).
const STRIP_EXACT = new Set([
  '_',                                   // jQuery/apploi cache buster (&_=1784956010.81)
