  'searchscreenid', 'ssbgcolor',         // Paychex AppOne search-screen skin
  'selectedmenukey'                      // ADP career-center menu state
]);
const STRIP_PREFIX = ['utm_', 'rx_', 'pk_', 'piwik_', 'hsa_'];
// Names too generic to strip everywhere — junk on these hosts only.
const STRIP_BY_HOST = [
  [/(^|\.)applitrack\.com$/, ['all', 'applitracklayoutmode', 'applitracksort', 'applitrackzipradius']]
];

function hostOf(u) {
  const m = u.match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].toLowerCase().replace(/:\d+$/, '') : '';
}

function cleanJobUrl(raw) {
  if (typeof raw !== 'string') return raw;
  const url = raw.trim();
  if (!/^https?:\/\//i.test(url)) return url;          // leave anything odd alone
  const hashAt = url.indexOf('#');
  let hash = hashAt >= 0 ? url.slice(hashAt) : '';
  if (/^#[0-9a-f]{3,8}$/i.test(hash)) hash = '';        // "#FFFFFF" — a colour, not an anchor
  const noHash = hashAt >= 0 ? url.slice(0, hashAt) : url;
  const qAt = noHash.indexOf('?');
  if (qAt < 0) return noHash + hash;                    // no query, nothing to strip
  const path = noHash.slice(0, qAt);
  const query = noHash.slice(qAt + 1);
  const host = hostOf(url);
  let hostExtra = null;
  for (let h = 0; h < STRIP_BY_HOST.length; h++) {
    if (STRIP_BY_HOST[h][0].test(host)) { hostExtra = STRIP_BY_HOST[h][1]; break; }
  }
  const kept = [];
  const parts = query.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (!part) continue;                                // stray "&&" (hrmDirect)
    const eq = part.indexOf('=');
    const name = (eq < 0 ? part : part.slice(0, eq)).toLowerCase();
    const value = eq < 0 ? '' : part.slice(eq + 1);
    if (!value) continue;                               // "Mod=", "&nohd" — carries no identity
    let strip = STRIP_EXACT.has(name);
    if (!strip && hostExtra) strip = hostExtra.indexOf(name) !== -1;
    if (!strip) {
      for (let p = 0; p < STRIP_PREFIX.length; p++) {
