// ── Decodo cost-tier escalation ──────────────────────────────────────────────
// Decodo costs 3x on premium+JS vs standard. Send the STANDARD pool first and
// escalate only when the answer is unusable — the same fallback shape as
// direct → Jina → Decodo, so nothing that resolves today can stop resolving,
// and a wrong guess costs one cheap request. This is the change that cut
// scraping spend by 42% with no loss of coverage.
//
// Judge the answer by SHAPE, never by emptiness: the bot-challenge pages that
// caused the worst misses were all NON-EMPTY. When unsure, escalate.
const DECODO_AUTH = '<DECODO_BASIC_AUTH>';   // read from an n8n credential, never inline
const DECODO_PREMIUM_HOSTS = /(example-retailer\.com|example-staffing\.com)/i;  // measured, not guessed
const DECODO_CHALLENGE = /(aws-waf-token|awswaf|Just a moment|cf-browser-verification|Checking your browser|Attention Required|Request unsuccessful|px-captcha|_pxhd|Pardon Our Interruption|challenge-platform|Incapsula|Access Denied)/i;
let DECODO_SD = null;
try { const sd = $getWorkflowStaticData('global'); sd.tier = sd.tier || {}; DECODO_SD = sd.tier; } catch (eSD) { DECODO_SD = {}; }
DECODO_SD.premiumHosts = DECODO_SD.premiumHosts || {};

// Code nodes are killed at 300 s, so retrying is abandoned once the node has already
// been running this long; a slow board must never be pushed over the limit by a retry
// meant for a flaky one.
const DECODO_T0 = Date.now();
const DECODO_RETRY_UNTIL_MS = 200000;
function decodoHostOf(u) {
  const m = String(u || '').match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}
// A learned escalation expires after 7 days, so a site that has since dropped its WAF
// goes back to the cheap pool instead of being pinned to premium forever by one bad
// afternoon.
function decodoWantsPremium(u) {
  if (DECODO_PREMIUM_HOSTS.test(String(u || ''))) return true;
  const h = decodoHostOf(u);
  const ts = h && DECODO_SD.premiumHosts[h];
  if (!ts) return false;
  if (Date.now() - ts > 7 * 864e5) { delete DECODO_SD.premiumHosts[h]; return false; }
  return true;
}
function decodoUsable(content) {
  const s = String(content || '');
  if (!s) return false;
  if (DECODO_CHALLENGE.test(s.slice(0, 4000))) return false;
  const t = s.trim();
  // a valid JSON/XML answer is good at ANY length — several handlers read tiny API replies
  if (t.charAt(0) === '{' || t.charAt(0) === '[') { try { JSON.parse(t); return true; } catch (eJ) { return false; } }
  if (/^<\?xml|^<urlset|^<sitemapindex/i.test(t)) return true;
  return s.length >= 1500;
}
const decodoReq = async function (body, timeout) {
  const send = async function (premium) {
    let r = await this.helpers.httpRequest({
      url: 'https://scraper-api.decodo.com/v2/scrape', method: 'POST',
      body: premium ? Object.assign({}, body, { proxy_pool: 'premium' }) : body,
      json: true,
      headers: { Authorization: DECODO_AUTH, 'Content-Type': 'application/json', Accept: 'application/json' },
      timeout: timeout || 120000
    });
    if (typeof r === 'string') r = JSON.parse(r);
    return r;
  }.bind(this);
  // ONE retry on a THROWN call. Twelve boards once reported failures on a single
  // afternoon and every one came back clean on a plain re-run the next day: they were
  // transient, and they clustered in contiguous batch positions, i.e. bad minutes
  // rather than bad boards. Deliberately narrow — retries only a thrown call, so the
  // usable/unusable CONTENT decision and the standard→premium escalation are untouched;
  // one extra attempt, so a hard-down host costs 2 calls, not 3+; and bounded by the
  // node-wide wall clock above.
  const decodoRetry = async function (premium) {
    try {
      return await send(premium);
    } catch (e1) {
      if (Date.now() - DECODO_T0 > DECODO_RETRY_UNTIL_MS) throw e1;
      DECODO_SD.retries = (DECODO_SD.retries || 0) + 1;
      await new Promise(function (r) { setTimeout(r, 2000); });
      return await send(premium);
    }
  }.bind(this);
  if (decodoWantsPremium(body && body.url)) return await decodoRetry(true);
  let first = null;
  try { first = await decodoRetry(false); } catch (eStd) { first = null; }
  const got = (first && first.results && first.results[0] && first.results[0].content) || '';
  if (decodoUsable(got)) return first;
  const h = decodoHostOf(body && body.url);
  if (h) DECODO_SD.premiumHosts[h] = Date.now();   // remember: go straight to premium next run
  return await decodoRetry(true);
}.bind(this);   // the OUTER function needs the bind too — send() reads this.helpers through it

const httpGet = async function (url, hdrs, tmo) {
  return await this.helpers.httpRequest({
    url: url, method: 'GET',
    headers: Object.assign({ 'User-Agent': UA, Accept: 'text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8', 'Accept-Language': 'en-US,en;q=0.9' }, hdrs || {}),
    timeout: tmo || 60000
