}.bind(this);

const ok = function (jobs, total) {
  return { json: Object.assign({}, item, { fetch_ok: true, fetch_error: '', total_found: total != null ? total : jobs.length, jobs: jobs }) };
};
const fail = function (e) {
  return { json: Object.assign({}, item, { fetch_ok: false, fetch_error: String((e && e.message) || e), total_found: 0, jobs: [] }) };
};
const allowAllStates = ALLOW_ALL_STATES_HOSTS.some(function (h) { return String(link || '').indexOf(h) !== -1; });
// A posting is kept when it names an allowed state, or names no state at all
// (those go on to the HQ rule downstream). It is dropped only on strong evidence
// of a state outside the list.
function keepByState(text) {
  if (allowAllStates) return { keep: true, state: null };
  const win = ' ' + String(text || '') + ' ';
  const sts = detectStatesText(win);
  const allowed = sts.filter(function (s) { return ALLOWED.has(s); });
  if (allowed.length) return { keep: true, state: allowed[0] };
  if (sts.length || strongNotAllowed(win)) return { keep: false, state: null };
  return { keep: true, state: null };
}

// ── Handler dispatch ─────────────────────────────────────────────────────────
// In production this is a chain of close to 40 branches, one per site type, each
// matching on the board URL and returning through ok() / fail(). Adding a site
// means adding a branch; nothing else in the pipeline changes. Two representative
// branches follow.

// ---- Greenhouse hosted boards: the official boards-api returns every job with
//      location.name in a single call, so no HTML parsing is needed at all. ----
const ghbM = String(link || '').match(/^https?:\/\/(?:job-boards|boards)(?:\.eu)?\.greenhouse\.io\/([A-Za-z0-9_-]+)/i);
if (ghbM) {
  try {
    let d = await httpGet('https://boards-api.greenhouse.io/v1/boards/' + ghbM[1].toLowerCase() + '/jobs?content=false', { Accept: 'application/json' });
    if (typeof d === 'string') d = JSON.parse(d);
    const list = (d && d.jobs) || [];
    if (!list.length) throw new Error('greenhouse boards-api: empty');
    const jobs = [];
    const seen = new Set();
    for (const j of list) {
      const id = j.id || j.absolute_url;
      if (!id || seen.has(id)) continue;
      seen.add(id);
      const verdict = keepByState((j.location && j.location.name) || '');
      if (!verdict.keep) continue;
      jobs.push({
        url: j.absolute_url || ('https://job-boards.greenhouse.io/' + ghbM[1].toLowerCase() + '/jobs/' + j.id),
        state: verdict.state,
        title: String(j.title || '').trim().slice(0, 120)
      });
    }
    return ok(jobs, list.length);
  } catch (e) { return fail(e); }
}

// ---- Generic JSON-LD fallback: any board that server-renders schema.org
//      JobPosting blocks. Tried directly first, then through Decodo if the page
//      is a JS shell or answers with a bot challenge. ----
try {
  let html = '';
  try { html = String(await httpGet(link)); } catch (eDirect) { html = ''; }
  if (!decodoUsable(html)) {
    const resp = await decodoReq({ url: link, geo: 'United States' }, 120000);
    html = (resp && resp.results && resp.results[0] && resp.results[0].content) || '';
  }
  if (!html) throw new Error('no content after escalation');

  const jobs = [];
  const seen = new Set();
  const ldRe = /<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi;
  let ld;
  while ((ld = ldRe.exec(html)) !== null) {
    let parsed;
    try { parsed = JSON.parse(ld[1].trim()); } catch (eLd) { continue; }
    const blocks = Array.isArray(parsed) ? parsed : [parsed];
    for (const b of blocks) {
      if (!b || b['@type'] !== 'JobPosting') continue;
      const url = b.url || b.sameAs || '';
      if (!url || seen.has(url)) continue;
      seen.add(url);
      const loc = b.jobLocation;
      const addr = (Array.isArray(loc) ? loc[0] : loc) || {};
      const region = (addr.address && (addr.address.addressRegion || addr.address.addressLocality)) || '';
      const verdict = keepByState(region || b.title || '');
      if (!verdict.keep) continue;
      jobs.push({ url: url, state: verdict.state, title: String(b.title || '').trim().slice(0, 120) });
    }
  }
  if (!seen.size) throw new Error('no JSON-LD JobPosting blocks found');
  return ok(jobs);
} catch (e) { return fail(e); }

// v51 (2026-08-13) — tell Slack how many links the day collected.
// Runs on the loop's DONE branch, i.e. once per batch, after the last company.
const RELAY = "https://<N8N_HOST>/webhook/joblinkos-notify-7d41c9";
const TZ = 'Asia/Manila';
const REPORT_INGEST = "https://<N8N_HOST>/webhook/joblinkos-linkreport-ingest-3b7e21";  // v63

// ⚠️ Everything is guarded. A notification must never be able to fail a run that
// has already collected the day's links.
let out = { notified: false, reason: 'not attempted' };
try {
  // 1 — which run is this? Prep Companies stamps every item (v40).
  let runMode = 'unknown';
  try { runMode = String(($('Prep Companies').first().json || {}).run_mode || 'unknown'); } catch (e) {}
  const mBatch = runMode.match(/^schedule-batch-(\d+)$/);
  const batch = mBatch ? Number(mBatch[1]) : 0;

  // 2 — count THIS batch. Format Sheet Rows runs once per company; an item with
  //     links_found true is one job link that reached the sheet. (Update Progress
  //     counts the same thing per company, so these agree with column G.)
  let links = 0, companies = 0, boards = 0;
  // v63 — same walk, also keyed by company so the day can be reported per board.
  const perCo = {}, zeroWhy = {};
  for (let r = 0; ; r++) {
    let items;
    try { items = $('Format Sheet Rows').all(0, r); } catch (e) { break; }
    if (!items) break;
    const kept = items.filter(i => i && i.json && i.json.links_found).length;
    links += kept;
    companies += 1;
    if (kept > 0) boards += 1;
    // ⚠️ A kept row names the company in "Company"; the links_found:false marker
    //    names it in lowercase "company". Both shapes have to be read.
    let name = null;
    for (const i of items) { const j = (i && i.json) || {}; if (j.Company) { name = j.Company; break; } }
    if (!name && items[0] && items[0].json) name = items[0].json.company || null;
    if (name) {
      perCo[name] = (perCo[name] || 0) + kept;
      const j0 = (items[0] && items[0].json) || {};
      if (kept === 0 && j0.links_found === false) {
        zeroWhy[name] = j0.fetch_ok ? 'board returned 0 jobs'
                                    : ('fetch failed: ' + (j0.fetch_error || '?'));
      } else { delete zeroWhy[name]; }
    }
  }


  // ⚠️ v84 — a company that produced links MUST have been stamped.
  // `Stamp Status (Fetched At)` runs downstream of `Append Links to NEW LINKS`, so a company
  // with links and no stamp is a company whose links never reached the sheet. Found the hard
  // way in production: one company produced 34 links, the append returned an EMPTY
  // result with no error at all, the stamp never ran, and the execution reported success.
  // v59 covers the append THROWING; nothing covered it succeeding-but-empty.
  const stampedNames = new Set();
  try {
    for (let r = 0; ; r++) {
      let items;
      try { items = $('Stamp Status (Fetched At)').all(0, r); } catch (eS) { break; }
      if (!items || !items.length) break;
      for (const it of items) {
        const nm = String(((it && it.json) || {}).Company || '').trim();
        if (nm) stampedNames.add(nm);
      }
    }
  } catch (eStamp) { /* never cost a run */ }
  const lostAppends = [];
  // ⚠️ only claim a loss when the stamp node actually produced names. If it ran but echoed no
  //    Company (a schema change, say), every company would look lost — a false alarm on all 300
  //    is worse than the silence this replaces.
  if (stampedNames.size) {
    for (const nm in perCo) {
      if (perCo[nm] > 0 && !stampedNames.has(nm)) lostAppends.push(nm + ' (' + perCo[nm] + ' links)');
    }
  }

  // v71 — the Companies tab travels with the report, so the Link Report can compare each
  //       board's count against the status operator wrote ("two jobs" ⇒ 2, "ok" ⇒ 3 or more)
  //       instead of posting a 300-line list.
  // ⚠️ It also names every row SKIPPED for a status no rule recognises. The v47 allowlist
  //    fails safe by skipping, so a relabel is otherwise completely invisible — which is
  //    exactly how 21 companies fell off the schedule on 2026-08-31.
  const statusBy = {}; const unknownStatus = [];
  try {
    // v81 (2026-09-03) — SYNCED VERBATIM from Prep Companies. These are a SECOND COPY of the
    // schedule rules; when they drift, the report invents "skipped" boards that did collect
    // (2026-09-02: 59 of them). Change them in Prep Companies and re-run fix_v81.
    const V71_NEVER = /^(?:site not allowed|states not allowed|site's job has no|website not allowed|website job (?:has no|states not allowed))/i;
    const V71_OFFL  = /\b(?:one[\s_-]*link|per[\s_-]*job)\b/i;
    const V71_ALLOW = /^(?:ok|scrape nationally|site has no job|site has one job|one job|one only|two jobs|site error|less than \d+ jobs?|website has no job|website error)\b/i;
    for (const it of $('Fetch Companies (operator)').all()) {
      const j = (it && it.json) || {};
      const nm = String(j.Company || '').trim();
      if (!nm) continue;
      const st = String(j.Status || '').trim();
      statusBy[nm] = st;
      const lk = String(j['Job Link'] || '').trim();
      if (!/^https?:\/\//i.test(lk)) continue;
      if (V71_NEVER.test(st) || V71_OFFL.test(st) || V71_ALLOW.test(st)) continue;
