  // 3 — add to the day's tally. The four batches are four executions, so this has
  //     to survive between them; static data does, and resets on a new day.
  // ⚠️ v81 — SCHEDULED batches only. Every execution used to add to the day tally, so a
  //    manual sheet-button run inflated that board and the NEXT day then read as a 50%
  //    crash (two boards read as 104->52 and 90->45 — both had really collected
  //    52 and 45 on BOTH days). A manual run still collects and still writes the sheet;
  //    it just no longer moves the day's report numbers.
  if (!batch) { out.reason = 'not a scheduled batch (' + runMode + ') - day tally untouched'; return [{ json: out }]; }
  const s = $getWorkflowStaticData('global');
  const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });   // YYYY-MM-DD
  if (s.notifyDay !== today) {
    s.notifyDay = today;
    s.notifyLinks = 0; s.notifyCompanies = 0; s.notifyBoards = 0; s.notifyBatches = [];
    s.notifyPerCompany = {}; s.notifyZeroWhy = {};                       // v63
  }
  if (!s.notifyPerCompany) s.notifyPerCompany = {};                      // v63
  if (!s.notifyZeroWhy) s.notifyZeroWhy = {};                            // v63
  // v71 — the whole tab is present in every batch, so the last write wins and is current.
  s.notifyStatusBy = statusBy;
  s.notifyUnknownStatus = unknownStatus;
  for (const k in perCo) s.notifyPerCompany[k] = (Number(s.notifyPerCompany[k]) || 0) + perCo[k];
  for (const k in zeroWhy) s.notifyZeroWhy[k] = zeroWhy[k];
