  //     manual run stop here, having spent nothing.
  if (batch !== 4) { out.reason = 'not batch 4 (' + runMode + ')'; return [{ json: out }]; }

  await this.helpers.httpRequest({
    method: 'POST', url: RELAY, json: true, timeout: 20000,
    body: {
      kind: 'links_collected',
      links: s.notifyLinks,
      companies: s.notifyCompanies,
      boards_with_links: s.notifyBoards,
      batches: (s.notifyBatches || []).length,
      day: today
    }
