  // v63 — hand the per-company breakdown to the Link Report workflow, which keeps
  // it so "Link Report" in Slack can answer instantly. ⚠️ Its own try/catch: the
  // day's Slack announcement above has already gone out and must not be undone
  // by a failure here.
  try {
    await this.helpers.httpRequest({
      method: 'POST', url: REPORT_INGEST, json: true, timeout: 20000,
      body: {
        day: today,
        links: s.notifyLinks, companies: s.notifyCompanies,
        boards_with_links: s.notifyBoards, batches: (s.notifyBatches || []).length,
        per_company: s.notifyPerCompany, zero_why: s.notifyZeroWhy,
        status_by: s.notifyStatusBy || {},                                  // v71
        unknown_status: s.notifyUnknownStatus || [],                        // v71
        lost_appends: s.notifyLostAppends || []                             // v84
      }
    });
    out.report_sent = true;
  } catch (e) {
    out.report_sent = false;
    out.report_error = e && e.message ? e.message : String(e);
  }
} catch (e) {
  out.notified = false;
  out.reason = 'notify failed: ' + (e && e.message ? e.message : String(e));
}
return [{ json: out }];
